package dev.zomboid.firstaid;
import fixture.Game.*;import net.minecraft.world.item.*;import net.minecraft.world.entity.EquipmentSlot;import net.minecraft.world.InteractionHand;import net.minecraft.world.effect.*;import com.raiiiden.warborn.common.util.NvgSupport33;import com.raiiiden.warborn.common.event.HelmetBatteryTickHandler;
public class MedicalChecks{
 static int checks;static void ok(boolean b,String m){checks++;if(!b)throw new AssertionError(m);}public static void main(String[]args){
  Actor p=new Actor();ItemStack defib=new ItemStack(new Item("firstaid:defibrillator"),1);p.setItemSlot(EquipmentSlot.OFFHAND,defib);p.setItemSlot(EquipmentSlot.MAINHAND,new ItemStack(new Item("firstaid:bandage"),1));Object selection=ReviveFix33.selection(p);ok(R.call(selection,"hand")==InteractionHand.OFF_HAND,"offhand defibrillator prioritized over main bandage");ok(ReviveFix33.duration(p,p)==60,"three second defibrillator");Actor bare=new Actor();ok(ReviveFix33.duration(bare,p)==160,"bare-hand other-player revive remains eight seconds");
  Client client=new Client();client.player=p;client.options.keyUse.down=true;Object prompt=ReviveFix33.prompt(client);ok(((Number)R.call(prompt,"holdDurationTicks")).intValue()==60,"self HUD continuous 60 ticks");ReviveFix33.clientTick(client);ReviveFix33.clientTick(client);ok(ichttt.mods.firstaid.FirstAid.NETWORKING.requests==1,"one request at start not every client frame");
  Assist.self(p);Assist.self(p);ok(Assist.attempts.size()==1,"one server attempt despite repeated requests");for(int tick=1;tick<=60;tick++){p.world.time=tick;Assist.tick(new Event(p,defib,0));}ok(!p.model.criticalConditionActive&&p.model.unconsciousTicks==0,"stale native rejection still leaves critical and unconscious states");ok(p.alive&&p.model.defibCalls==1&&defib.damage==1,"revived once one defibrillator charge");for(Part part:p.model.parts)ok(part.currentHealth>=3,"all eight parts stabilized");ok(p.tag.getLong("FABleedGraceUntil")==460,"twenty second bandaging grace");ok(Assist.attempts.isEmpty(),"attempt removed on completion");Assist.self(p);ok(Assist.attempts.isEmpty()&&defib.damage==1,"completed player does not enter infinite self-revive loop");
  Actor interrupted=new Actor();interrupted.setItemSlot(EquipmentSlot.MAINHAND,new ItemStack(new Item("firstaid:defibrillator"),1));Assist.self(interrupted);interrupted.setItemSlot(EquipmentSlot.MAINHAND,ItemStack.EMPTY);interrupted.world.time=1;Assist.tick(new Event(interrupted,ItemStack.EMPTY,0));ok(!Assist.attempts.containsKey(interrupted),"removing defibrillator interrupts attempt");
  p.using=true;p.use=new ItemStack(new Item("firstaid:zombie_cure_injector"),1);ok(MedicineProgress33.active(client),"generic infection cure now included in medicine HUD");ok(MedicineProgress33.duration(p)==32,"duration 1.6 seconds");MedicineProgress33.tick(new Event(p,p.use,16));ok(p.messages.get(p.messages.size()-1).contains("50"),"visible fifty percent progress");MedicineProgress33.finished(new Event(p,p.use,0));ok(p.messages.get(p.messages.size()-1).contains("medicine33.complete"),"completion feedback");p.use=new ItemStack(new Item("firstaid:prophylactic_antibiotic"),1);ok(MedicineProgress33.active(client),"antibiotic generic use included");p.using=false;ok(!MedicineProgress33.active(client),"HUD stops on interrupted use");
  Actor nvg=new Actor();int energy=50000;for(int second=1;second<=900;second++){int drain=NvgSupport33.drain(5,nvg);ok(drain==55||drain==56,"fractional battery drain bounded");energy-=drain;if(second<900)ok(energy>0,"battery lasts full fifteen minutes");}ok(energy==0,"exactly 50000 energy in 900 active seconds");
  Object holder=MobEffects.NIGHT_VISION;nvg.addEffect(new MobEffectInstance(holder,100,1,false,true,true));HelmetBatteryTickHandler.nvgActiveMap.put(nvg.uuid,"simple_nvg");HelmetBatteryTickHandler.batteryEnergyCache.put(nvg.uuid,50000);NvgSupport33.player(nvg);ok(nvg.getEffect(holder).getDuration()==-1,"infinite NVG effect while battery active");nvg.world.time=20;HelmetBatteryTickHandler.nvgActiveMap.remove(nvg.uuid);NvgSupport33.player(nvg);ok(nvg.getEffect(holder).getDuration()==80&&nvg.getEffect(holder).getAmplifier()==1,"original potion retained with elapsed time");nvg.effects.clear();for(String mode:new String[]{"simple_nvg","nvg","digital","thermal","thermal_white","thermal_black"}){HelmetBatteryTickHandler.nvgActiveMap.put(nvg.uuid,mode);HelmetBatteryTickHandler.batteryEnergyCache.put(nvg.uuid,1);NvgSupport33.player(nvg);ok(nvg.getEffect(holder).getDuration()==-1,"night vision for mode "+mode);HelmetBatteryTickHandler.batteryEnergyCache.put(nvg.uuid,0);NvgSupport33.player(nvg);ok(nvg.getEffect(holder)==null,"no leftover infinite effect after depletion "+mode);}
  System.out.println("MEDICAL_CHECKS="+checks);
 }
}
